+ source:"JMA",n03Version:"20260101",basetime:"20261112120000",
+ frames:[{validTime:"20261112120500",municipalities:areas.map(a=>({...a,prefecture:"東京都",municipality:a.code==="13108"?"江東区":"中央区"}))}]
+});
